"""Offline assembly of the KJA Stage A package. Reads only this directory."""
from pathlib import Path
import csv, json, hashlib, datetime, collections

ROOT=Path(__file__).resolve().parent
ASOF='2026-11-12'
def put(name,obj):
 (ROOT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def table(name,rows):
 fields=list(dict.fromkeys(k for row in rows for k in row))
 with (ROOT/name).open('w') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
def readcsv(name):return list(csv.DictReader((ROOT/name).open()))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

# Keep only the last successful receipt as the current source. Superseded digests
# remain in the acquisition history but never point to a different retained text.
receipts=json.loads((ROOT/'fetch_receipts.json').read_text())
latest={r['source_id']:r for r in receipts}
for r in receipts:
 if r is not latest[r['source_id']] and r.get('text_path'):
  r['superseded_text_path']=r.pop('text_path');r['retained_text']=False;r['superseded_by_text_sha256']=latest[r['source_id']].get('text_sha256')
put('fetch_receipts.json',receipts)

